H.background();
const m = Math.max(P.m, 0.1);
const v = Math.max(P.v, 0.1);
const r = Math.max(P.r, 0.3);
const Fc = m * v * v / r;
const omega = v / r;
H.text("Centripetal force: Fc = m v^2 / r", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Net inward force keeps the mass on its circular path", 24, 52, { color: H.colors.sub, size: 13 });
const cx = H.W * 0.52, cy = H.H * 0.56;
const R = 150;
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, 4, { fill: H.colors.sub });
const ang = omega * t;
const px = cx + R * Math.cos(ang);
const py = cy - R * Math.sin(ang);
H.line(cx, cy, px, py, { color: H.colors.axis, width: 1, dash: [4, 4] });
const ax = (cx - px), ay = (cy - py);
const aMag = Math.sqrt(ax * ax + ay * ay) || 1;
const fLen = Math.min(40 + Fc * 1.5, R - 14);
H.arrow(px, py, px + ax / aMag * fLen, py + ay / aMag * fLen, { color: H.colors.warn, width: 5 });
H.text("Fc", px + ax / aMag * (fLen + 16), py + ay / aMag * (fLen + 16), { color: H.colors.warn, size: 13, align: "center", baseline: "middle" });
const rDot = 8 + m * 2.5;
H.circle(px, py, Math.min(rDot, 22), { fill: H.colors.accent2, stroke: H.colors.ink, width: 2 });
H.text("m = " + m.toFixed(1) + " kg", 24, 76, { color: H.colors.accent2, size: 13 });
H.text("v = " + v.toFixed(1) + " m/s   r = " + r.toFixed(1) + " m", 24, 96, { color: H.colors.accent, size: 13 });
H.text("Fc = m v^2 / r = " + Fc.toFixed(1) + " N", 24, 120, { color: H.colors.warn, size: 15, weight: 700 });
H.text("(doubling v quadruples Fc)", 24, 140, { color: H.colors.sub, size: 12 });
